MM.mnemo[7] = {"cards":[{"id":"ko-k3-0150","w":"모으다","cs":"sbírat; šetřit (peníze)","en":"to save up, to collect","p":"v","o":"k","ex":"돈을 모아서 뭐 할 거예요?","exc":"Co uděláš s penězi, které našetříš? (을 → 4. pád; -아서 → a pak)","m":"Pravidelné ㅡ: 모아요, 모았어요. 돈을 모으다 = šetřit peníze, 우표를 모으다 = sbírat známky.","tv":["모아요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0152","w":"아프다","cs":"nemocný; bolet","en":"to be sick, to hurt","p":"a","o":"k","ex":"지민 씨는 아파서 집에 갔어요.","exc":"Džimin bylo špatně, tak šla domů. (-아서 → protože, tak; 에 → kam)","m":"Znamená ‚být nemocný‘ (celkově) i ‚bolet‘ (konkrétní část těla s částicí 이/가, např. 머리가 아파요 = bolí mě hlava). Pozor na nepravidelné časování ㅡ: 아프다 → 아파요.","tv":["아파요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0153","w":"비슷하다","cs":"podobný","en":"to be similar","p":"a","o":"k","ex":"영어랑 비슷해서요.","exc":"Protože je to podobné angličtině. (랑 → s / jako; -아서/어서요 → protože)","m":"Pojí se se spojovacími částicemi ‚s‘: -하고, -(이)랑 nebo -와/과 (např. 한국어랑 비슷해요 = je to podobné korejštině). Opakem je 다르다 (odlišný, jiný).","tv":["비슷해요"]},{"id":"ko-k3-0155","w":"-에 따라서","cs":"podle (čeho), v závislosti na","en":"according to ~","p":"f","o":"k","ex":"계획에 따라서 진행하겠습니다.","exc":"Budeme postupovat podle plánu. (-겠습니다 → zdvořilý záměr)","m":"Doslova ‚následujíce (něco)‘ – ze slovesa 따르다 (následovat, řídit se něčím; nepravidelné ㅡ → 따라). V hovoru se často zkracuje na -에 따라 (상황에 따라 달라요 = záleží na situaci)."},{"id":"ko-k3-0156","w":"예를 들어서","cs":"například","en":"for example","p":"f","o":"m","ex":"예를 들어서 설명해 주세요.","exc":"Vysvětlete mi to prosím na příkladu. (-아/어 주세요 → prosba)","m":"例 příklad + 들다 (zvednout, uvést) = uvést příklad, tedy ‚například‘. V hovoru se často zkracuje na 예를 들어.","r":["ye-例"]},{"id":"ko-k3-0157","w":"계획","cs":"plán","en":"plan","p":"n","o":"s","ex":"계획에 따라서 진행하겠습니다.","exc":"Budeme postupovat podle plánu. (-에 따라서 → podle)","m":"計 počítat + 劃 rozvrhnout = rozpočítat si to dopředu. 계획을 세우다 = udělat plán.","hada":1,"r":["gye-計","hoek-劃"]},{"id":"ko-k3-0158","w":"진행하다","cs":"pokračovat, probíhat; vést (akci, pořad)","en":"to proceed","p":"v","o":"m","ex":"계획에 따라서 진행하겠습니다.","exc":"Budeme postupovat podle plánu. (-에 따라서 → podle; -겠습니다 → zdvořilý záměr)","m":"進 postupovat vpřed + 行 jít, konat (+ 하다) = posouvat věc dopředu, tedy pokračovat v něčem nebo vést program. Podstatné jméno 진행 znamená ‚průběh‘ a 진행자 je ‚moderátor‘.","r":["jin-進","haeng-行"]},{"id":"ko-k3-0159","w":"반갑다","cs":"rád (že někoho vidí), potěšený","en":"to be glad to see someone","p":"a","o":"k","ex":"만나서 반가워요.","exc":"Rád vás poznávám / Rád tě vidím. (-아서 → protože, že)","m":"Vyjadřuje radost ze shledání nebo seznámení (만나서 반가워요 / 반갑습니다). Pozor na nepravidelné časování ㅂ: kmen 반갑- se před samohláskou mění na 반가워- (반가워요)."},{"id":"ko-k3-0160","w":"피곤하다","cs":"unavený","en":"to be tired","p":"a","o":"m","ex":"잠을 많이 자서 전혀 피곤하지 않아요.","exc":"Hodně jsem se vyspal, takže nejsem vůbec unavený. (을 → 4. pád; -아서 → protože, takže; -지 않아요 → zápor)","m":"疲 únava + 困 vyčerpaný (+ 하다) = být unavený. Kořen 疲 najdeš i ve slově 피로 (únava, vyčerpání); v korejštině je to přídavné jméno, takže ‚jsem unavený‘ se řekne jednoduše 피곤해요.","r":["pi-疲","gon-困"],"tv":["피곤해요"]},{"id":"ko-k3-0161","w":"장학금","cs":"stipendium","en":"scholarship","p":"n","o":"s","ex":"열심히 공부해서 장학금을 받을 거예요.","exc":"Budu se pilně učit, a tak dostanu stipendium. (-아서/어서 → a tak; 을 → 4. pád)","m":"獎 odměna + 學 studium + 金 peníze = finanční odměna za studium, tedy stipendium. Kořen 金 (peníze) znáš ze slova 현금 (hotovost) a 學 ze slova 학교 (škola).","r":["jang-獎","hak-學","geum-金"]},{"id":"ko-k3-0162","w":"열심히","cs":"pilně, usilovně, tvrdě","en":"hard, diligently","p":"o","o":"m","ex":"열심히 공부해서 장학금 받을 거예요.","exc":"Budu se pilně učit a dostanu stipendium. (-아서/어서 → a tak)","m":"熱 horký, horlivý + 心 srdce + -히 (přípona příslovce) = s horlivým srdcem, tedy pilně a naplno. Častá spojení: 열심히 공부하다 (pilně se učit) a 열심히 일하다 (tvrdě pracovat).","r":["yeol-熱","sim-心"]},{"id":"ko-k3-0163","w":"요즘","cs":"v poslední době, teď, v dnešní době","en":"these days","p":"n","o":"k","ex":"요즘에 바빠서 친구들을 못 만나요.","exc":"V poslední době mám napilno, takže se nemůžu vídat s kamarády. (에 → kdy; -아서 → protože; 못 → nemoci)","m":"Zkrácenina z 요즈음 (v těchto dnech). Používá se jak s částicí 에 (요즘에), tak velmi často samostatně bez částice na začátku věty (요즘 어때요? = Jak se v poslední době máš?)."},{"id":"ko-k3-0164","w":"전혀","cs":"vůbec (ne), naprosto (ne)","en":"not at all (with a negative)","p":"o","o":"m","ex":"잠을 많이 자서 전혀 피곤하지 않아요.","exc":"Hodně jsem se vyspal, takže nejsem vůbec unavený. (을 → 4. pád; -아서 → protože, takže; -지 않아요 → zápor)","m":"全 celý, úplný + přípona -혀: pojí se téměř vždy se záporem (전혀 몰라요 = vůbec nevím, 전혀 안 피곤해요 = nejsem vůbec unavený) a zesiluje ho na ‚naprosto ne‘.","r":["jeon-全"]},{"id":"ko-k3-0165","w":"잠","cs":"spánek","en":"sleep (noun)","p":"n","o":"k","ex":"잠을 많이 자서 전혀 피곤하지 않아요.","exc":"Hodně jsem se vyspal, takže nejsem vůbec unavený. (을 → 4. pád; -아서 → protože, takže; -지 않아요 → zápor)","m":"Podstatné jméno od slovesa 자다 (spát). V korejštině se často používají obě slova dohromady ve vazbě 잠을 자다 (spát spánek), zvlášť když chceš říct ‚hodně spát‘ (잠을 많이 자다) nebo ‚nemoci usnout‘ (잠이 안 오다)."},{"id":"ko-k3-0167","w":"중국어","cs":"čínština","en":"Chinese (language)","p":"n","o":"s","ex":"한국어보다 중국어가 더 쉬워요?","exc":"Je čínština jednodušší než korejština? (보다 → než; 가 → 1. pád)","m":"中國 Čína (Střední země) + 語 jazyk. 語 jako v 한국어, 영어.","r":["jung-中","guk-國","eo-語"]},{"id":"ko-k3-0168","w":"설명하다","cs":"vysvětlit, vysvětlovat","en":"to explain","p":"v","o":"m","ex":"예를 들어서 설명해 주세요.","exc":"Vysvětlete mi to prosím na příkladu. (-아/어 주세요 → prosba)","m":"說 říci, vyložit + 明 jasný (+ 하다) = vyložit něco tak, aby to bylo jasné, tedy vysvětlit. Podstatné jméno 설명 znamená ‚vysvětlení‘ a 설명서 je ‚návod k použití‘.","r":["seol-說","myeong-明"]},{"id":"ko-k3-0169","w":"매일","cs":"každý den; denně","en":"every day","p":"o","o":"s","ex":"한국어가 너무 재미있어서 매일 공부하고 있어요.","exc":"Korejština je tak zábavná, že se ji učím každý den. (가 → 1. pád; -어서 → protože)","m":"每 každý + 日 den = každý den. 日 jako v 일요일 (neděle) nebo 생일 (narozeniny).","r":["mae-每","il-日"]}],"gram":{"id":"ko-k3-g07","w":"-아/어/여서","en":"Linking Verbs","cs":"protože, a tak; a potom (příčina a návaznost)","vy":"Koncovka -아서/어서/여서 se tvoří stejně jako přítomný čas bez koncového -요. Vyjadřuje buď příčinu a následek (‚protože…, a tak…‘), nebo těsnou posloupnost dějů, kdy druhý děj navazuje na první na stejném místě či s tímže předmětem. Před touto koncovkou nikdy nestojí minulý ani budoucí čas (ten se vyjadřuje až u posledního slovesa) a v příčinném významu se nepojí s rozkazem ani výzvou.","m":"Na rozdíl od neutrálního -고 spojuje -아서/어서 děje vnitřním poutem — buď jeden způsobil druhý (‚pršelo, a tak nejdu‘), nebo druhý bezprostředně navazuje na první (‚koupit dort a dát ho kamarádovi‘).","s":[["비가 와서 못 가요.","Prší, takže nemůžu jít."],["비가 와서 못 갔어요.","Pršelo, takže jsem nemohl jít."],["오늘은 바빠서 영화를 못 봐요.","Dneska mám napilno, takže se na ten film nemůžu podívat."],["만나서 반가워요.","Rád vás poznávám."],["공원에 가서 책을 읽을 거예요.","Půjdu do parku a budu si tam číst knihu."],["친구를 만나서 밥을 먹었어요.","Sešel jsem se s kamarádem a najedli jsme se spolu."],["돈을 모아서 뭐 할 거예요?","Co uděláš s penězi, které našetříš?"],["케이크를 사서 친구한테 줄 거예요.","Koupím dort a dám ho kamarádovi."],["계획에 따라서 진행하겠습니다.","Budu postupovat podle plánu."],["예를 들어서, 이렇게 할 수 있어요.","Například to můžete udělat takhle."],["한국에 가서 뭐 할 거예요?","Co budeš dělat, až pojedeš do Koreje?"],["서울에 와서 좋아요.","Jsem rád, že jsem přijel do Soulu."],["잠을 많이 자서 전혀 피곤하지 않아요.","Hodně jsem se vyspal, takže nejsem vůbec unavený."],["열심히 공부해서 장학금을 받을 거예요.","Budu se pilně učit, a tak dostanu stipendium."],["왜요? — 영어랑 비슷해서요.","Proč? — Protože je to podobné angličtině."],["너무 많이 먹어서 배불러요.","Snědl jsem toho moc, takže jsem plný."],["여기 와서 이거 보세요.","Pojďte sem a podívejte se na tohle."],["예를 들어서 설명해 주세요.","Vysvětlete to prosím na příkladu."]]}};
Object.assign(MM.mnRoots, {"ye-例":["예","例","příklad, pravidlo"],"gye-計":["계","計","počítat, plánovat"],"hoek-劃":["획","劃","rozvrhnout"],"jin-進":["진","進","postupovat vpřed"],"haeng-行":["행","行","jít, konat"],"pi-疲":["피","疲","únava"],"gon-困":["곤","困","unavený, v tísni"],"jang-獎":["장","獎","odměna, povzbudit"],"hak-學":["학","學","učení, škola"],"geum-金":["금","金","zlato, peníze"],"yeol-熱":["열","熱","horko"],"sim-心":["심","心","srdce, mysl"],"jeon-全":["전","全","celý, úplný"],"jung-中":["중","中","střed, Čína"],"guk-國":["국","國","země, stát"],"eo-語":["어","語","jazyk, řeč"],"seol-說":["설","說","říci, vyložit"],"myeong-明":["명","明","jasný"],"mae-每":["매","每","každý"],"il-日":["일","日","den, slunce"]});
